def transform(grid):
    from collections import Counter

    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    all_cells = [cell for row in grid for cell in row]
    bg = Counter(all_cells).most_common(1)[0][0]

    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Find right-edge markers (col w-1, non-bg)
    right_edge_val = None
    for r in range(h):
        if grid[r][w-1] != bg and grid[r][w-1] != 0:
            right_edge_val = grid[r][w-1]
            break

    # If right-edge marker found, it indicates fill region starts
    if right_edge_val is not None:
        # Find scattered markers (non-bg, non-left-edge, non-right-edge)
        scatter_rows = set()
        for r in range(h):
            for c in range(1, w-1):
                if grid[r][c] != bg:
                    scatter_rows.add(r)

        # For each row with scatter marker, fill from scatter position to right edge
        for r in range(h):
            if r in scatter_rows:
                # Find first scatter in this row
                for c in range(1, w-1):
                    if grid[r][c] != bg:
                        first_scatter = c
                        break
                else:
                    continue

                scatter_val = grid[r][first_scatter]
                # Fill from scatter position to right edge (exclusive) with scatter_val
                for c_fill in range(first_scatter, w-1):
                    result[r][c_fill] = scatter_val
                # Convert scatter marker itself to 4
                result[r][first_scatter] = 4

    return result
